import os
import json
import base64
import secrets
from dataclasses import dataclass
from typing import Any, Dict, Optional

import boto3
from botocore.exceptions import BotoCoreError, ClientError


@dataclass
class EnvelopeCiphertext:
    key_id: str
    kms_encrypted_data_key: str
    nonce: str
    ciphertext: str
    associated_data: Optional[str] = None

    def to_json(self) -> str:
        return json.dumps(
            {
                "key_id": self.key_id,
                "kms_encrypted_data_key": self.kms_encrypted_data_key,
                "nonce": self.nonce,
                "ciphertext": self.ciphertext,
                "associated_data": self.associated_data,
            },
            separators=(",", ":"),
        )

    @staticmethod
    def from_json(payload: str) -> "EnvelopeCiphertext":
        obj = json.loads(payload)
        return EnvelopeCiphertext(
            key_id=obj["key_id"],
            kms_encrypted_data_key=obj["kms_encrypted_data_key"],
            nonce=obj["nonce"],
            ciphertext=obj["ciphertext"],
            associated_data=obj.get("associated_data"),
        )


class AWSEnvelopeEncryption:
    """
    Envelope encryption using AWS KMS for key wrapping and AES-GCM for data encryption.

    Required environment variables (AWS SDK):
      - AWS_ACCESS_KEY_ID
      - AWS_SECRET_ACCESS_KEY
      - AWS_REGION (optional, defaults to us-east-1)
    """

    def __init__(self, kms_key_id: str, region_name: Optional[str] = None) -> None:
        self.kms_key_id = kms_key_id
        self.region_name = region_name or os.getenv("AWS_REGION", "us-east-1")
        self.kms = boto3.client("kms", region_name=self.region_name)

    def encrypt(self, plaintext: bytes, associated_data: Optional[bytes] = None) -> str:
        try:
            data_key = self.kms.generate_data_key(
                KeyId=self.kms_key_id,
                KeySpec="AES_256",
            )
            plaintext_data_key = data_key["Plaintext"]
            encrypted_data_key = data_key["CiphertextBlob"]

            nonce = secrets.token_bytes(12)
            aesgcm = self._aesgcm()
            ciphertext = aesgcm_encrypt(
                aesgcm,
                plaintext_data_key,
                nonce,
                plaintext,
                associated_data,
            )

            envelope = EnvelopeCiphertext(
                key_id=self.kms_key_id,
                kms_encrypted_data_key=base64.b64encode(encrypted_data_key).decode("utf-8"),
                nonce=base64.b64encode(nonce).decode("utf-8"),
                ciphertext=base64.b64encode(ciphertext).decode("utf-8"),
                associated_data=base64.b64encode(associated_data).decode("utf-8")
                if associated_data is not None
                else None,
            )
            return envelope.to_json()
        except (BotoCoreError, ClientError) as e:
            raise RuntimeError(f"AWS KMS envelope encryption failed: {e}") from e

    def decrypt(self, envelope_json: str) -> bytes:
        try:
            envelope = EnvelopeCiphertext.from_json(envelope_json)
            encrypted_data_key = base64.b64decode(envelope.kms_encrypted_data_key)
            nonce = base64.b64decode(envelope.nonce)
            ciphertext = base64.b64decode(envelope.ciphertext)
            associated_data = (
                base64.b64decode(envelope.associated_data)
                if envelope.associated_data is not None
                else None
            )

            data_key_resp = self.kms.decrypt(
                CiphertextBlob=encrypted_data_key,
                KeyId=envelope.key_id,
            )
            plaintext_data_key = data_key_resp["Plaintext"]

            aesgcm = self._aesgcm()
            return aesgcm_decrypt(
                aesgcm,
                plaintext_data_key,
                nonce,
                ciphertext,
                associated_data,
            )
        except (BotoCoreError, ClientError) as e:
            raise RuntimeError(f"AWS KMS envelope decryption failed: {e}") from e

    @staticmethod
    def _aesgcm():
        try:
            from cryptography.hazmat.primitives.ciphers.aead import AESGCM
        except ImportError as e:
            raise RuntimeError("cryptography package is required for AES-GCM") from e
        return AESGCM


def aesgcm_encrypt(aesgcm_cls: Any, key: bytes, nonce: bytes, plaintext: bytes, associated_data: Optional[bytes]) -> bytes:
    return aesgcm_cls(key).encrypt(nonce, plaintext, associated_data)


def aesgcm_decrypt(aesgcm_cls: Any, key: bytes, nonce: bytes, ciphertext: bytes, associated_data: Optional[bytes]) -> bytes:
    return aesgcm_cls(key).decrypt(nonce, ciphertext, associated_data)
